export function calculate(model, scenarioId, factor=1){
 if(!Number.isFinite(factor)||factor<0||factor>1.5)throw new Error('Volume inválido');
 const s=model.scenarios.find(s=>s.id===scenarioId);if(!s)throw new Error('Cenário inválido');
 const a=model.assumptions, fixed=Object.values(s.fixedCash).reduce((v,n)=>v+n,0);
 const lines=model.offers.map(o=>{const qty=Math.round(s.quantities[o.id]*factor),revenue=qty*o.price,cost=qty*o.directCost+revenue*(o.paymentRate+a.taxReserveRate+a.refundReserveRate);return {...o,qty,revenue,cost,hours:qty*o.coordinationHours};});
 const revenue=lines.reduce((v,l)=>v+l.revenue,0),cost=lines.reduce((v,l)=>v+l.cost,0),cashResult=revenue-cost-fixed,unpaid=s.founderUnpaidHours*a.founderHourlyValue+a.existingAssetsAllocation,hours=lines.reduce((v,l)=>v+l.hours,0)+a.sharedHours;
 return {scenario:s,lines,fixed,revenue,cost,cashResult,economicResult:cashResult-unpaid,unpaid,hours,capacity:s.coordinationCapacityHours,capacityExceeded:hours>s.coordinationCapacityHours,cash90:(fixed*3+s.setupCash+s.workingCapital)*(1+a.contingencyRate),breakeven:revenue>cost?fixed/(1-cost/revenue):null};
}
